{"path": "unique.mjs", "content": "export function uniqueBy(items, key = "id") {
  const seen = new Map();
  const result = [];

  for (const item of items) {
    const value = item[key];

    if (!seen.has(value)) {
      seen.set(value, true);
      result.push(item);
    }
  }

  return result;
}
"}

